<script setup lang="ts">
import {dialogueLabels} from './dialogue-labels';
import {useTranscriptActivation} from './useTranscriptActivation';
import {useSpeakerUndo} from './useSpeakerUndo';
import Icon from '../../shared/Icon.vue';
import {computed,onUnmounted,ref,shallowRef,watch,nextTick} from 'vue';
import {useApplication} from '../../application';
import {useTranscriptEditor} from './useTranscriptEditor';
import TranscriptSpeakerPanel from './TranscriptSpeakerPanel.vue';
import CorrectionPanel from './CorrectionPanel.vue';
import {useSpeechCorrections} from './useSpeechCorrections';
import TranscriptForm from './TranscriptForm.vue';
import TranscriptOperationsDialog from './TranscriptOperationsDialog.vue';
import {useTranscriptOperations} from './useTranscriptOperations';
import {ApiError} from '../../shared/api/client';
import type {TranscriptDetail,TranscriptHistory} from '../../shared/api/transcripts';
import type {MediaScope} from './useSourceMedia';
import type {TranscriptEdits} from './transcript-journal';
const speakerPanel=ref<InstanceType<typeof TranscriptSpeakerPanel>>();
const props=withDefaults(defineProps<{meetingId:string;active?:boolean;resultKey?:string;showFooter?:boolean;published?:boolean}>(),{showFooter:true,active:true,resultKey:''});const emit=defineEmits<{changed:[];confirmed:[];seek:[fileId:string,startMs:number]}>();const form=ref<InstanceType<typeof TranscriptForm>>(),confirmDialog=ref<HTMLDialogElement>();const {session,transcripts,transcriptOperations,transcriptCorrections,workspace,journals,meetingScope,transcriptScopeReady}=useApplication();
const actor=()=>session.current.value?.actor.enterpriseId??null,eligible=()=>meetingScope.value===props.meetingId&&transcriptScopeReady.value;
const editor=useTranscriptEditor({...transcripts,authorize:async(id,signal)=>(await workspace.navigation(id,signal)).relation==='OWNER'},actor,()=>props.meetingId,eligible,journals),localError=ref<string|null>(null),history=shallowRef<TranscriptHistory|null>(null),selected=shallowRef<TranscriptDetail|null>(null),historyBusy=ref(false),raw=shallowRef<TranscriptDetail|null>(null);
const leaveDialog=ref<HTMLDialogElement>();let leaveDecision:((allowed:boolean)=>void)|null=null;
const toolsOpen=ref(false),toolsError=ref<string|null>(null);
const canUseTools=()=>!!editor.saved.value?.capabilities.canSave&&!editor.draft.value?.dirty.value&&!editor.draft.value?.conflict.value&&!editor.busy.value&&!editor.loading.value&&!editor.recoveryBlocked.value&&editor.pendingOperation()===null&&['EMPTY','ACKNOWLEDGED'].includes(editor.command.state.value);
const tools=useTranscriptOperations({...transcriptOperations,current:transcripts.current},{actor,meeting:()=>props.meetingId,eligible,canMutate:()=>canUseTools()&&!corrections.pending.value,current:()=>editor.saved.value,context:journals});
const correctionError=ref<string|null>(null),bulkBusy=ref(false);
const corrections=useSpeechCorrections({...transcriptCorrections,current:transcripts.current},{actor,meeting:()=>props.meetingId,eligible,canMutate:()=>canUseTools()&&!tools.pending.value,current:()=>editor.saved.value,context:journals});
const stopCorrections=watch(()=>[actor(),props.meetingId,eligible()],()=>{correctionError.value=null;try{corrections.synchronize();}catch(cause){correctionError.value=cause instanceof Error?cause.message:'纠错恢复记录暂不可用。';}},{immediate:true,flush:'sync'});
async function loadCorrections(){const who=actor(),id=props.meetingId;try{correctionError.value=null;await corrections.load();}catch(cause){if(who===actor()&&id===props.meetingId&&eligible()&&!denyReview(cause))correctionError.value=cause instanceof Error?cause.message:'纠错建议暂不可用。';}}
async function correctionAction(action:()=>Promise<unknown>){if(bulkBusy.value)return;const who=actor(),id=props.meetingId;try{correctionError.value=null;await action();if(who!==actor()||id!==props.meetingId||!eligible())return;if(!corrections.pending.value){localError.value=null;await editor.reload();await loadCorrections();}}catch(cause){if(who===actor()&&id===props.meetingId&&eligible()&&!denyReview(cause))correctionError.value=cause instanceof Error?cause.message:'纠错暂无法核实，请保留原请求。';}}
async function bulkCorrections(decision:'ACCEPT'|'REJECT'){
 if(bulkBusy.value||!canUseTools()||tools.pending.value||corrections.pending.value)return;const who=actor(),meeting=props.meetingId;const ids=corrections.view.value?.items.filter(x=>decision==='ACCEPT'?x.canAccept:x.canReject).map(x=>x.id)??[];if(!ids.length)return;
 bulkBusy.value=true;correctionError.value=null;
 try{for(const id of ids){if(who!==actor()||meeting!==props.meetingId||!eligible())throw new DOMException('Correction scope changed','AbortError');await corrections.decide(id,decision);await editor.reload();if(editor.error.value)throw editor.error.value;await corrections.load();}}
 catch(cause){if(who===actor()&&meeting===props.meetingId&&eligible()&&!denyReview(cause))correctionError.value=cause instanceof Error?cause.message:'批量处理已停止，请核实原操作。';}
 finally{bulkBusy.value=false;}
}
const reviewDialog=ref<HTMLDialogElement>();
const canReview=computed(()=>!!editor.saved.value?.capabilities.canReadHistory&&!editor.loading.value);
const speakerUndo=useSpeakerUndo({revision:transcripts.revision},{actor,meeting:()=>props.meetingId,active:()=>eligible()&&!!reviewDialog.value?.open,canMutate:()=>canUseTools()&&!tools.pending.value&&!corrections.pending.value,current:()=>editor.saved.value,undo:()=>toolAction(tools.undo),denied:denyReview});
const canEditSpeakers=computed(()=>canReview.value&&!!(editor.saved.value?.saved||raw.value?.selected)&&!speakerUndo.checking.value&&!historyBusy.value&&!bulkBusy.value&&!editor.busy.value&&!tools.pending.value&&!corrections.pending.value);
function openReview(){if(!actor()||!eligible()||!canReview.value)return;if(!reviewDialog.value?.open)reviewDialog.value?.showModal();}
function closeReview(event?:Event){if(!actor()||!eligible()){speakerUndo.cancel();reviewDialog.value?.close();return;}if(bulkBusy.value||editor.busy.value||tools.pending.value||corrections.pending.value){event?.preventDefault();localError.value='原转写或纠错操作结果尚未确认，请先恢复原操作。';return;}speakerUndo.cancel();reviewDialog.value?.close();}
async function undoLatest(){localError.value=null;openReview();await speakerUndo.run();if(canReview.value&&tools.pending.value)toolsOpen.value=true;}
watch(()=>[corrections.pending.value,canReview.value,actor(),eligible()],()=>{if(corrections.pending.value&&canReview.value)void nextTick().then(()=>{if(corrections.pending.value)openReview();});},{flush:'post'});
const stopTools=watch(()=>[actor(),props.meetingId,eligible()],()=>{speakerUndo.cancel();reviewDialog.value?.close();toolsOpen.value=false;toolsError.value=null;try{tools.synchronize();if(tools.pending.value)toolsOpen.value=true;}catch(cause){toolsError.value=cause instanceof Error?cause.message:'修订恢复记录暂不可用。';}},{immediate:true,flush:'sync'});
watch(()=>[editor.saved.value?.saved?.id,editor.saved.value?.observation.revisionToken].join(':'),()=>{tools.clearSearch();corrections.clearView();if(editor.saved.value?.correction.mode==='CONTROLLED_SPEECH'&&!corrections.pending.value)void loadCorrections();});
function denyReview(cause:unknown){if(!(cause instanceof ApiError)||![401,403].includes(cause.status??0))return false;clearHistory();editor.deny(cause);speakerUndo.cancel();reviewDialog.value?.close();toolsOpen.value=false;emit('changed');return true;}
async function toolAction(action:()=>Promise<unknown>,refresh=true){if(bulkBusy.value||corrections.pending.value)return;const who=actor(),id=props.meetingId;toolsError.value=null;try{await action();if(who!==actor()||id!==props.meetingId||!eligible())return;if(!tools.pending.value){localError.value=null;if(refresh)await editor.reload();}}catch(cause){if(who===actor()&&id===props.meetingId&&eligible()&&!denyReview(cause))toolsError.value=cause instanceof Error?cause.message:'修订暂无法核实，请保留原请求。';}}
function discardTool(){try{tools.discardRejected();toolsError.value=null;void editor.reload();}catch(cause){toolsError.value=cause instanceof Error?cause.message:'原修订暂无法清理。';}}
let epoch=0,controller:AbortController|null=null;
function clearHistory(){raw.value=null;epoch++;controller?.abort();controller=null;history.value=null;selected.value=null;historyBusy.value=false;localError.value=null;}
const stop=watch(()=>[actor(),props.meetingId,eligible()],()=>{clearHistory();if(actor()&&eligible())void editor.reload();},{immediate:true,flush:'sync'});
watch(()=>editor.saved.value,async value=>{if(value)emit('changed');raw.value=null;if(value&&!value.saved&&value.capabilities.canReadHistory){await inspect(null);const original=history.value?.items.find(x=>x.kind==='RAW');if(original){await inspect(original.id);if(selected.value?.selected.kind==='RAW')raw.value=selected.value;}}});
const permissionStop=watch(()=>editor.saved.value?.capabilities.canReadHistory,allowed=>{if(!allowed)clearHistory();},{flush:'sync'});
const stopActivation=useTranscriptActivation(()=>props.active,()=>props.resultKey,()=>!eligible()||editor.busy.value||!['EMPTY','ACKNOWLEDGED'].includes(editor.command.state.value)||!!editor.draft.value?.dirty.value||editor.pendingOperation()!==null||tools.pending.value||corrections.pending.value,()=>editor.reload());
const stopLogout=session.onLogout(()=>{corrections.dispose();correctionError.value=null;tools.dispose();toolsOpen.value=false;toolsError.value=null;editor.logout();});
const message=computed(()=>localError.value??(editor.error.value instanceof Error?editor.error.value.message:null));
const readonlyContent=computed(()=>(editor.saved.value?.saved??raw.value?.selected)?.segments.map(({segmentId,body,marks})=>({segmentId,body,marks}))??[]);
const sourceDetail=computed(()=>editor.saved.value?.saved?editor.saved.value:raw.value);
const provenance=computed(()=>editor.saved.value?.saved?.segments??raw.value?.selected.segments??[]);
const fileLabels=computed(()=>dialogueLabels(provenance.value));
const media=computed<MediaScope|null>(()=>{const d=sourceDetail.value;if(!d?.capabilities.canReadSources)return null;const ids=new Set(provenance.value.filter(s=>s.startMs!==null&&s.endMs!==null).map(s=>s.sourceFileId)),revisionId=d===raw.value?raw.value!.selected.id:null;return{meeting:props.meetingId,revisionId,accessRevisionToken:d.observation.accessRevisionToken,sources:d.sources.filter(s=>ids.has(s.fileId)&&d.sourceBytes.some(b=>b.fileId===s.fileId&&b.eligibility==='ELIGIBLE')).map(s=>({fileId:s.fileId,sha256:s.sha256,sizeBytes:s.sizeBytes,ordinal:s.ordinal,revisionId,recordingWav:d.parserVersion==='ama.recording-wav.v1'}))};});
function edit(value:TranscriptEdits){if(tools.pending.value||corrections.pending.value)return;try{localError.value=null;editor.edit(value);}catch(cause){localError.value=cause instanceof Error?cause.message:'修改暂不可用。';}}
function resolve(action:'reapply'|'discard'){try{localError.value=null;editor[action]();}catch(cause){localError.value=cause instanceof Error?cause.message:'请先处理原操作。';}}
async function inspect(id:string|null,more=false){
 if(!actor()||!eligible()||!editor.saved.value?.capabilities.canReadHistory)return;const turn=++epoch,who=actor(),meeting=props.meetingId;controller?.abort();const request=new AbortController();controller=request;historyBusy.value=true;localError.value=null;
 const active=()=>turn===epoch&&who===actor()&&meeting===props.meetingId&&eligible()&&editor.saved.value?.capabilities.canReadHistory;
 try{if(id){const result=await transcripts.revision(meeting,id,request.signal);if(active())selected.value=result;}else{const result=await transcripts.history(meeting,more?history.value?.nextCursor??null:null,request.signal);if(active()){history.value=result;selected.value=null;}}}
 catch(cause){if(active()){clearHistory();localError.value=cause instanceof Error?cause.message:'历史读取暂不可用。';if(cause instanceof ApiError&&cause.kind==='http'&&[401,403].includes(cause.status??0))editor.deny(cause);}}
 finally{if(active())historyBusy.value=false;}
}
async function save(){if(!bulkBusy.value&&!tools.pending.value&&!corrections.pending.value&&!form.value?.composing)await editor.save();}
async function commit(value:TranscriptEdits,expected:string):Promise<boolean>{
 if(bulkBusy.value||tools.pending.value||corrections.pending.value||form.value?.composing||!editor.draft.value||editor.busy.value||editor.recoveryBlocked.value)return false;
 const original=editor.command.snapshot.value,pending=editor.pendingOperation()!==null&&!['CONFLICT','REJECTED'].includes(editor.command.state.value);
 if(pending){if(original?.operation!=='TRANSCRIPT_SAVE')return false;await editor.retry();}
 else{if(expected!==editor.saved.value?.observation.revisionToken){localError.value='转写或纠错已变化，请核对后重试';return false;}try{editor.edit(value);}catch(cause){localError.value=cause instanceof Error?cause.message:'修改暂不可用。';return false;}await editor.save();}
 return !editor.error.value&&!editor.draft.value?.dirty.value&&!editor.draft.value?.conflict.value;
}
async function confirm(){if(bulkBusy.value||tools.pending.value||corrections.pending.value||form.value?.composing)return;if(editor.draft.value?.dirty.value)await editor.save();if(editor.error.value||editor.draft.value?.dirty.value)return;if(!editor.saved.value?.confirmation?.isCurrent)await editor.confirm();if(editor.saved.value?.confirmation?.isCurrent&&!editor.error.value)emit('confirmed');}
async function begin(){if(bulkBusy.value||tools.pending.value||corrections.pending.value)return;const id=editor.saved.value?.saved?.id??raw.value?.selected.id;if(!id)return;await editor.reload();if(editor.error.value||editor.draft.value?.dirty.value)return;await editor.restore(id);}
async function beforeLeave(){if(bulkBusy.value)return false;if(corrections.pending.value){openReview();localError.value='请先恢复或处理原纠错操作。';return false;}if(tools.pending.value){toolsOpen.value=true;return false;}if(editor.pendingOperation()!==null&&!['CONFLICT','REJECTED'].includes(editor.command.state.value)){localError.value='请先恢复原转写操作结果。';return false;}if(!editor.draft.value?.dirty.value)return true;if(leaveDecision)return false;return new Promise<boolean>(resolve=>{leaveDecision=resolve;leaveDialog.value?.showModal();});}
async function decideLeave(choice:'save'|'discard'|'stay'){if(choice==='save'){await save();if(editor.error.value||editor.draft.value?.dirty.value)return;}if(choice==='discard'){try{editor.discard();}catch(cause){localError.value=cause instanceof Error?cause.message:'草稿暂无法处理。';return;}}leaveDialog.value?.close();leaveDecision?.(choice!=='stay');leaveDecision=null;}
async function openSpeakers(){if(bulkBusy.value||tools.pending.value||corrections.pending.value){localError.value='请先恢复或处理当前修订请求。';return;}if(editor.saved.value?.saved?.kind!=='WORKING')await begin();openReview();await loadCorrections();await nextTick();speakerPanel.value?.focus();}
defineExpose({beforeLeave,save,media,openSpeakers,openReview,undoLatest,canReview,canEditSpeakers,sourceState:computed(()=>editor.loading.value||historyBusy.value?'loading':message.value?'error':sourceDetail.value?'ready':'empty'),speakerLabels:computed(()=>[...(corrections.speakers.value?.items.map(x=>({id:x.id,label:x.label,enterpriseId:x.enterpriseId,segments:x.segmentIds.length}))??[]),...fileLabels.value.items]),dirty:computed(()=>!!editor.draft.value?.dirty.value||tools.pending.value||corrections.pending.value)});
onUnmounted(()=>{stopActivation();leaveDecision?.(false);leaveDecision=null;stop();stopTools();stopCorrections();corrections.dispose();tools.dispose();permissionStop();stopLogout();clearHistory();editor.dispose();});
</script>
<template>
 <TranscriptForm :simulated-speech="sourceDetail?.parserVersion==='ama.media-documents.v3'&&provenance.some(s=>s.startMs!==null)" :file-labels="fileLabels.labels" :speaker-labels="Object.fromEntries(corrections.speakers.value?.items.map(x=>[x.id,x.label])??[])" :corrections-ready="!!corrections.view.value" :correction-count="corrections.view.value?.pendingCount??0" :pending-correction-segments="corrections.view.value?.items.filter(x=>x.status==='PENDING').map(x=>x.segmentId)??[]" @accept-all="bulkCorrections('ACCEPT')" @reject-all="bulkCorrections('REJECT')" :published="published" @tools="toolsOpen=true" ref="form" :pending-save="editor.pendingOperation()==='TRANSCRIPT_SAVE'&&!['CONFLICT','REJECTED'].includes(editor.command.state.value)" :revision-token="editor.saved.value?.observation.revisionToken" :commit="commit" :provenance="provenance" :playable-files="media?.sources.map(s=>s.fileId)??[]" @seek="(fileId,startMs)=>emit('seek',fileId,startMs)" :show-footer="showFooter" @begin="begin" v-if="editor.draft.value||editor.saved.value?.saved||raw" :value="editor.saved.value?.saved?editor.draft.value?.value.value??readonlyContent:readonlyContent" :editable="!!editor.draft.value&&!!editor.saved.value?.capabilities.canSave" :busy="bulkBusy||editor.busy.value||tools.busy.value||corrections.busy.value" :dirty="editor.draft.value?.dirty.value??false" :conflict="editor.draft.value?.conflict.value?.value??null" :conflict-token="editor.draft.value?.conflict.value?.token??null" :state="editor.command.state.value" :blocked="editor.recoveryBlocked.value||tools.pending.value||corrections.pending.value" :blocked-reason="corrections.pending.value?'请先恢复或处理原纠错操作。':tools.pending.value?'请先恢复或处理原修订请求。':undefined" :storage-status="editor.storageStatus.value" :error="message" :confirmed="!!editor.saved.value?.confirmation?.isCurrent" :can-confirm="!!editor.saved.value?.capabilities.canConfirm" @edit="edit" @save="save" @confirm="confirmDialog?.showModal()" @retry="editor.retry" @reload="editor.reload" @discard="resolve('discard')" @reapply="resolve('reapply')"/>
 <section v-else class="card transcript-feedback"><h2>转写正文</h2><p v-if="editor.loading.value" role="status">正在读取转写…</p><p v-else-if="message" role="alert">{{message}}</p><p v-else>尚无已保存转写。导入任务完成后重新读取。</p><button class="btn" :disabled="editor.loading.value" @click="editor.reload">重新读取转写</button></section>
 <dialog v-if="!published" ref="reviewDialog" class="transcript-review-dialog" aria-labelledby="transcript-review-title" @cancel="closeReview($event)"><header class="review-header"><h3 id="transcript-review-title">转写版本与语音审阅</h3><button type="button" class="btn sm ghost" aria-label="关闭转写审阅" @click="closeReview"><Icon name="x" :size="18"/></button></header><div class="review-body"><p v-if="speakerUndo.checking.value" role="status">正在核对当前说话人变更…</p><p v-if="speakerUndo.message.value" role="status">{{speakerUndo.message.value}}</p><p v-if="localError" role="alert">{{localError}}</p><div class="flex mb16"><button type="button" class="btn sm" @click="toolsOpen=true">纠错建议与候选</button><button type="button" class="btn sm" :disabled="editor.busy.value||editor.recoveryBlocked.value" @click="editor.retry">恢复原操作结果</button><button v-if="editor.draft.value?.dirty.value||['CONFLICT','REJECTED'].includes(editor.command.state.value)" type="button" class="btn sm" @click="resolve('discard')">放弃本地修改／已拒绝操作</button></div>
 <details v-if="!published&&editor.saved.value?.capabilities.canReadHistory" class="transcript-history"><summary>转写历史与原操作恢复</summary><section class="card transcript-feedback"><h2>转写历史</h2><button class="btn" :disabled="historyBusy" @click="inspect(null)">读取历史版本</button><ul v-if="history"><li v-for="item in history.items" :key="item.id"><button class="btn" :disabled="historyBusy" @click="inspect(item.id)">{{item.kind==='RAW'?'原始转写 RAW':'人工工作版本 WORKING'}} · {{item.revisionToken}} · {{item.createdAt}}</button></li></ul><button v-if="history?.hasMore" class="btn" :disabled="historyBusy" @click="inspect(null,true)">下一页历史</button><article v-if="selected"><h3>{{selected.selected.kind==='RAW'?'原始转写':'历史工作版本'}} · {{selected.selected.revisionToken}}</h3><p v-for="s in selected.selected.segments.slice(0,40)" :key="s.segmentId" class="text">{{s.body}}</p><p v-if="selected.selected.segments.length>40">显示前 40 段；恢复会使用所选完整版本。</p><button class="btn" :disabled="bulkBusy||tools.pending.value||corrections.pending.value||editor.busy.value||editor.draft.value?.dirty.value||!!editor.draft.value?.conflict.value||!selected.capabilities.canRestore" @click="editor.restore(selected.selected.id)">恢复为新的工作版本</button></article></section></details>
 <section v-if="!published&&editor.saved.value?.capabilities.canReadHistory&&editor.saved.value?.correction.mode==='CONTROLLED_SPEECH'" class="card transcript-feedback" aria-label="语音增强建议"><h2>语音增强建议</h2><p class="small muted">建议来自本次语音处理结果，接受后建立新的人工工作版本；原始转写始终保留。</p><div class="flex"><button class="btn sm" :disabled="bulkBusy||corrections.busy.value" @click="loadCorrections">读取纠错建议</button><button class="btn sm" :disabled="bulkBusy||!canUseTools()||tools.pending.value||corrections.pending.value||corrections.busy.value||!corrections.view.value?.canPropose" @click="correctionAction(corrections.propose)">检查语音增强建议</button><button v-if="corrections.pending.value" class="btn sm" :disabled="bulkBusy||corrections.busy.value" @click="correctionAction(corrections.retry)">恢复原纠错操作</button><button v-if="['CONFLICT','REJECTED'].includes(corrections.command.state.value)" class="btn sm" @click="corrections.discardRejected();loadCorrections()">放弃已拒绝的纠错请求</button></div><p v-if="corrections.loading.value" role="status">正在核实语音来源…</p><p v-if="correctionError" role="alert">{{correctionError}}</p><TranscriptSpeakerPanel ref="speakerPanel" v-if="corrections.speakers.value" :snapshot="corrections.speakers.value" :segments="editor.saved.value?.saved?.segments??[]" :busy="bulkBusy||corrections.busy.value||corrections.pending.value||tools.pending.value" :editable="canUseTools()" @label="(segments,label,enterpriseId)=>correctionAction(()=>corrections.label(segments,label,enterpriseId))" @merge="(source,target)=>correctionAction(()=>corrections.merge(source,target))"/><CorrectionPanel v-if="corrections.view.value" :corrections="corrections.view.value.items" :busy="bulkBusy||!canUseTools()||tools.pending.value||corrections.pending.value||corrections.busy.value" @decision="(id,decision)=>correctionAction(()=>corrections.decide(id,decision==='accept'?'ACCEPT':'REJECT'))" @undo="id=>correctionAction(()=>corrections.undo(id))"/></section>
 </div></dialog>
 <TranscriptOperationsDialog :suggestions-available="!!corrections.view.value" v-if="toolsOpen&&actor()&&eligible()" :matches="tools.matches.value" :segments="editor.saved.value?.saved?.segments??[]" :pending="tools.pending.value" :busy="bulkBusy||tools.busy.value" :searching="tools.searching.value" :can-mutate="canUseTools()&&!corrections.pending.value" :state="tools.command.state.value" :original="tools.original.value" :error="toolsError" @search="query=>toolAction(()=>tools.search(query),false)" @replace="(replacement,ids)=>toolAction(()=>tools.replace(replacement,ids))" @undo="toolAction(tools.undo)" @retry="toolAction(tools.retry)" @discard="discardTool" @close="toolsOpen=false"/>
 <dialog ref="leaveDialog" class="notice-dialog" aria-labelledby="transcript-leave-title" @cancel.prevent="decideLeave('stay')"><h3 id="transcript-leave-title">处理未保存的转写修改</h3><p>离开前可保存当前工作稿，或放弃本地修改。</p><div class="flex mt16"><button class="btn" @click="decideLeave('stay')">继续核对</button><button class="btn" :disabled="editor.busy.value" @click="decideLeave('discard')">放弃修改并离开</button><button class="btn primary" :disabled="editor.busy.value" @click="decideLeave('save')">保存并离开</button></div></dialog>
 <dialog ref="confirmDialog" class="notice-dialog" aria-labelledby="confirm-transcript-title"><h3 id="confirm-transcript-title">确认转写并生成纪要</h3><p class="mt16">确认后将使用当前已保存转写作为纪要依据。未保存的修改会先保存，生成内容仍需人工核对。</p><p class="small muted mt12">确认、模板设置和纪要生成分别记录结果；发生中断时可查回原操作。</p><div class="flex mt16"><button class="btn" @click="confirmDialog?.close()">返回校正</button><button class="btn primary" :disabled="editor.busy.value" @click="confirm().then(()=>{if(editor.saved.value?.confirmation?.isCurrent)confirmDialog?.close();})">确认并生成</button></div></dialog>
</template>
<style scoped>.transcript-feedback{padding:24px;margin-bottom:20px}.transcript-feedback h2{font-size:18px}.text{white-space:pre-wrap;overflow-wrap:anywhere}li{margin:8px 0}button:disabled{opacity:.5}</style>

<style scoped>.transcript-history{margin:12px 0;color:var(--muted);font-size:12px}.transcript-history summary{cursor:pointer}.transcript-feedback{box-shadow:none}</style>

<style scoped>.transcript-review-dialog{margin:auto;width:min(920px,calc(100vw - 32px));max-height:88dvh;overflow:auto;padding:0;border:0;border-radius:10px;color:var(--text)}.transcript-review-dialog::backdrop{background:rgba(17,24,73,.35)}.review-header{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid var(--border)}.review-header h3{font-size:15px;margin:0}.review-body{padding:20px}.review-body>p[role=alert]{color:var(--red);margin-bottom:12px}</style>
